Senda.Knowledge:Register({
  id = "druid-bracket-10-19",
  class = "DRUID",
  kind = "page",
  title = "Niveles 10-19: la Forma de oso",
  levels = {10, 19},
  order = 20,
  status = "unverified",
  note = "Cadenas de misiones de clase comprobadas en QuestieDB (Forever). Rotación de oso: Method (7-nov) y Warcraft Tavern.",
  block = {
    { heading = "Zonas", body = "- **10-12:** termina Teldrassil (Dolanaar) y sube a **Darnassus** a entrenar.\n- **12-19:** **Costa Oscura**, con base en Auberdine (barco desde Embarcadero de Rut'theran).\n\nMazmorras:\n- **Hall of Thanes** (13-18) en Forjaz y **Ruins of Lordaeron** (15-20): lejos para un elfo de la noche, solo con grupo hecho.\n- **Minas de la Muerte** (17-22) y **Cuevas de los Lamentos** (17-24)." },
    { heading = "Formas", body = "- **10: Forma de oso** con la misión de clase (no se compra al instructor). Con ella: Gruñido, Magullar y Rugido desmoralizador.\n- **16: Forma acuática** con otra misión de clase: nadas más rápido y respiras bajo el agua. Te da el **Ídolo de las mareas cambiantes** (Idol of Shifting Tides), que abarata cambiar de forma.\n\nHasta el 20 el oso es tu forma de combate: aguanta golpes y no gasta maná.", note = "Nombre esES del ídolo sin confirmar; lo da la misión de la Forma acuática según Warcraft Tavern." },
    { heading = "Hechizos", body = "- **10:** Forma de oso (misión), Teletransporte: Claro de la Luna, Garras de la naturaleza (de base en Forever).\n- **12:** Recrecimiento, Enfurecer, **Revivir** (resurrección fuera de combate, nueva).\n- **14:** Azote, Curar envenenamiento (misión de clase).\n- **16:** Flagelo, Forma acuática (misión).\n- **18:** Fuego feérico (de base en Forever, ya no es talento), Hibernar." },
    { heading = "Talentos", body = "- **10-14:** Ferocidad 5/5 (Magullar, Flagelo, Arañazo y Arañar más baratos).\n- **15-16:** Celeridad feral 2/2 (esquiva ya; +30% de velocidad en felino desde el 20).\n- **17-19:** Piel gruesa 3/3.", note = "Árbol según la calculadora de timesaver (Forever). Nombres esES de Celeridad feral y Piel gruesa sin confirmar." },
    { heading = "Rotación", body = "**Un enemigo:** Cólera x2 desde lejos, Fuego lunar, **Forma de oso** cuando llegue, Enfurecer, Rugido desmoralizador, Magullar en cada golpe.\n\n**Varios:** Forma de oso, Enfurecer, Rugido desmoralizador y Flagelo (desde el 16).\n\nContra lanzadores no gastes ira en el Rugido." },
    { heading = "Misiones de clase", body = "- **10: Atender la llamada** (Kal en Dolanaar o Denatharion en Darnassus) » **Claro de la Luna** (Mathrengyl Bearwalker, Darnassus) » **Gran espíritu del oso** (Dendrite Starblaze, Claro de la Luna) » **De vuelta a Darnassus**. Recompensa: Forma de oso.\n- **14: Lecciones de nuevo** (Lessons Anew, Mathrengyl) » Claro de la Luna » Costa Oscura (Alanndarian Nightsong, 37.7, 40.7). Recompensa: Curar envenenamiento.\n- **16: Una lección que aprender** (A Lesson to Learn) » **Prueba del lago** » **Prueba del león marino** (Costa Oscura) » **Forma acuática**.", note = "Títulos esES de las misiones sin confirmar; ids 5923/5925, 5921, 5929, 5931, 6121-6125, 26, 29, 272, 5061." },
    { heading = "Macros", body = "- **Al 10:** SND_Oso (entra en oso sin quitártelo), SND_Gru (Gruñido al ratón o al objetivo).\n- **Al 16:** SND_Viaje (en el agua, Forma acuática; luego, la mejor forma de viaje que tengas).\n- **Al 18:** SND_Feerico (Fuego feérico en cualquier forma)." },
    { heading = "Profesiones", body = "- Objetivo al 20: Herboristería ~125, Alquimia ~110.\n- Costa Oscura: Marregal, Brezospina, Alga estranguladora y Hierba cardenal.\n- Entrena Oficial (rango 2) al 10 en Dolanaar; Experto al 20 en Darnassus." },
    { heading = "Equipo", body = "- Prioridad: **DPS del arma**, Fuerza, Agilidad, Aguante. Un bastón o maza de dos manos con buen DPS vale más que cualquier verde de Intelecto.\n- Hombreras de la serpiente (Serpent's Shoulders, Cuevas de los Lamentos) y Gran martillo de Smite (Minas de la Muerte), si vas en grupo." },
    { heading = "Oro", body = "Vende las hierbas que no uses (Marregal y Brezospina se venden bien). El Teletransporte: Claro de la Luna ahorra la piedra de hogar para entrenar." },
    { heading = "Objetivos", body = "- Forma de oso al 10, Forma acuática al 16.\n- Nivel 20 con unas 2-3 de oro guardadas para entrenar Forma felina y los rangos del 20." },
    { heading = "Consejos", body = "- Teletransporte: Claro de la Luna te deja junto a un instructor de druida (Loganaar) y un maestro de vuelo a Darnassus.\n- En Forever puedes usar consumibles y hablar con la mayoría de PNJ **sin salir de la forma**.\n- Cúrate entre combates en forma normal (SND_Cura) y vuelve a oso: no esperes a que se llene el maná." },
  },
})

Senda.Knowledge:Register({
  id = "druid-bracket-20-29",
  class = "DRUID",
  kind = "page",
  title = "Niveles 20-29: la Forma felina",
  levels = {20, 29},
  order = 30,
  status = "unverified",
  note = "La misión de la Forma felina es nueva en Forever (cadena 98393-98397 en QuestieDB). Rotación de felino: Method y Warcraft Tavern.",
  block = {
    { heading = "Zonas", body = "- **18-25:** Vallefresno (Astranaar).\n- **20-25:** Sierra Espolón o Los Humedales (barco Auberdine » Menethil).\n- **20-30:** Montañas Crestagrana y Bosque del Ocaso, si vas al este.\n\nMazmorras:\n- **Cavernas de Brazanegra** (20-27), en Vallefresno: la más cómoda para un elfo de la noche.\n- **Excavation Site: Wetlands** (24-29).\n- **Gnomeregan** y el Cementerio del Monasterio Escarlata al final del tramo." },
    { heading = "Formas", body = "- **20: Forma felina** con la misión **El gran espíritu felino** (Mathrengyl Bearwalker, Darnassus » Dendrite Starblaze, Claro de la Luna). Te da Arañazo, Acechar y Destripar.\n- Desde aquí el felino es tu forma de subir: mata más rápido. El oso queda para cuando te peguen varios.\n- **Celeridad feral** ya da +30% de velocidad en felino: corre en felino entre enemigos." },
    { heading = "Hechizos", body = "- **20:** Forma felina, Arañazo, Acechar, Destripar, Triturar (baja al 20), Fuego estelar, Renacer, Augurio de claridad (de base). Armas de asta (Woo Ping, Ventormenta).\n- **22:** Calmar animal.\n- **24:** Arañar, Mordedura feroz (baja al 24), Eliminar maldición.\n- **26:** Carrerilla, Suprimir veneno.\n- **28:** Rugido desafiante, Agazaparse." },
    { heading = "Talentos", body = "- **20:** Cargar feral.\n- **21-22:** Garras afiladas 2/2.\n- **23-24:** Furia salvaje 2/2.\n- **25-27:** Golpes depredadores 3/3.\n- **28-29:** Frenesí de sangre 2/2.", note = "Nombre esES de Frenesí de sangre sin confirmar." },
    { heading = "Rotación", body = "1. Acechar y abre con **Triturar** por la espalda (o Cargar feral).\n2. **Fuego feérico**, **Arañar** (desde el 24).\n3. **Arañazo** hasta 4-5 puntos de combo.\n4. **Destripar** si va a vivir todo el sangrado; si no, **Mordedura feroz**.\n\nEn Forever los puntos de combo no se pierden al cambiar de objetivo (pero tampoco pasan al nuevo)." },
    { heading = "Misiones de clase", body = "- **20: El gran espíritu felino** (98393, Mathrengyl Bearwalker, Darnassus) » Dendrite Starblaze (Claro de la Luna) » el Gran espíritu felino (58.4, 73.5) » **A Darnassus**. Hay también **Bendiciones del Gran espíritu felino** (98731) en el Claro de la Luna.", note = "Títulos esES sin confirmar. La 98731 no tiene recompensa conocida." },
    { heading = "Macros", body = "- **Al 20:** SND_Abrir (una tecla: felino, Acechar, abrir y Arañazo), SND_Gato (vuelve a felino y te quitas raíces), SND_Carga." },
    { heading = "Profesiones", body = "- Entrena **Experto** (rango 3) al 20 en Darnassus: Firodren Mooncaller (Herboristería, 48.0, 68.0) y Ainethil (Alquimia, 54.9, 24.0).\n- Objetivo al 30: Herboristería ~170, Alquimia ~160.\n- Vallefresno y Los Humedales: Hierba cardenal, Acérita salvaje, Sangrerregia y Raíz de vida." },
    { heading = "Equipo", body = "- **Armas de asta** desde el 20 (Woo Ping, Ventormenta): en Forever las formas escalan con el DPS del arma.\n- Gran martillo de Smite (Minas de la Muerte) y el conjunto Abrazo de la víbora (Cuevas de los Lamentos) si vas en grupo." },
    { heading = "Oro", body = "- Guarda para el 30 (Forma de viaje y rangos) y empieza a apartar para la montura del 40.\n- Las pociones de maná de Alquimia (Poción de maná inferior) se venden bien a otros lanzadores." },
    { heading = "Objetivos", body = "- Forma felina el mismo día que llegas al 20.\n- Un arma de dos manos con buen DPS antes del 25." },
    { heading = "Consejos", body = "- Acechar te deja elegir pelea: pasa entre grupos sin que te vean.\n- Si te pegan dos, no te quedes en felino: Forma de oso o Raíces enredadoras al segundo (SND_Raices con foco).\n- Cúrate fuera de combate en forma normal y vuelve a felino: el Augurio de claridad abarata el siguiente golpe." },
  },
})

