Senda.Knowledge:Register({
  id = "druid-macros",
  class = "DRUID",
  kind = "macros",
  title = "Macros del druida",
  order = 90,
  status = "unverified",
  note = "Macros escritas por el autor; ninguna guía de Forever publica macros de druida. Sin probar en el juego. No se usan números de [form:N] porque el orden de las formas depende de las que conozcas.",
  macro = {
    { name = "SND_Cura", icon = "spell:8936", minlevel = 1, body = "#showtooltip\n/cancelform [form]\n/cast [mod:alt,@player] {774}; [@mouseover,help,nodead][@player] {8936}", fallbacks = {"#showtooltip\n/cancelform [form]\n/cast [mod:alt,@player] {774}; [@player] {5185}", "#showtooltip\n/cast [@player] {5185}"}, note = "Sale de la forma y te cura: Recrecimiento (al ratón si es amistoso, si no a ti); con Alt, Rejuvenecimiento. Antes del 12, Toque de sanación." },
    { name = "SND_Raices", icon = "spell:339", minlevel = 8, body = "#showtooltip {339}\n/cast [@focus,harm,nodead][@mouseover,harm,nodead][] {339}", note = "Raíces enredadoras al foco, al ratón o al objetivo. En Forever valen en interiores." },
    { name = "SND_Oso", icon = "spell:5487", minlevel = 10, body = "#showtooltip\n/cast !{9634}", fallbacks = {"#showtooltip\n/cast !{5487}"}, note = "Entra en Oso temible (40) u Oso sin quitártelo si ya estás en él." },
    { name = "SND_Gru", icon = "spell:6795", minlevel = 10, body = "#showtooltip {6795}\n/cast [@mouseover,harm,nodead][] {6795}", note = "Gruñido al enemigo bajo el ratón (para quitárselo a un compañero) o a tu objetivo." },
    { name = "SND_Viaje", icon = "spell:783", minlevel = 16, body = "#showtooltip\n/cast [swimming] !{1066}; [outdoors] !{783}; !{768}", fallbacks = {"#showtooltip\n/cast [swimming] !{1066}; !{768}", "#showtooltip\n/cast !{1066}"}, note = "En el agua, Forma acuática; al aire libre, Forma de viaje (30); dentro, Forma felina (con Celeridad feral corre un 30% más). Antes del 20 solo la acuática." },
    { name = "SND_Feerico", icon = "spell:770", minlevel = 18, body = "#showtooltip {770}\n/cast [@mouseover,harm,nodead][] {770}", note = "Fuego feérico al ratón o al objetivo. En Forever es de base y se usa en forma; si en forma el hechizo tiene otro id, cámbialo aquí." },
    { name = "SND_Gato", icon = "spell:768", minlevel = 20, body = "#showtooltip {768}\n/cancelform [form]\n/cast {768}", fallbacks = {"#showtooltip {768}\n/cast !{768}"}, note = "Vuelve a entrar en Forma felina: quita raíces y ralentizaciones. En Forever Furor ya no da energía al cambiar (la conserva) y el «cambio de forma con poder» lo sustituye Poder cambiante: esto es para escapar, no para ganar energía." },
    { name = "SND_Abrir", icon = "spell:6785", minlevel = 20, body = "#showtooltip\n/cast [noform] !{768}; [nostealth,nocombat] {5215}; [stealth] {6785}; {1082}", fallbacks = {"#showtooltip\n/cast [noform] !{768}; [nostealth,nocombat] {5215}; [stealth] {5221}; {1082}"}, note = "Una tecla para todo el felino: sin forma, Forma felina; fuera de combate, Acechar; en sigilo, Devastar (32) o Triturar; en combate, Arañazo." },
    { name = "SND_Carga", icon = "spell:16979", minlevel = 20, body = "#showtooltip\n/cast [@mouseover,harm,nodead][] {1238122}", fallbacks = {"#showtooltip\n/cast [@mouseover,harm,nodead][] {16979}"}, note = "Cargar feral (talento del 20): en oso inmoviliza e interrumpe, en felino salta detrás. 1238122 es el id de Forever según Warcraft Tavern; 16979, el de Classic." },
    { name = "SND_Poder", icon = "spell:1322605", minlevel = 40, body = "#showtooltip\n/cast {1322605}", note = "Poder cambiante (talento del 40): maná por 40 de energía sin salir del felino. Id de Warcraft Tavern, sin comprobar." },
    { name = "SND_Estimular", icon = "spell:29166", minlevel = 40, body = "#showtooltip {29166}\n/cast [@mouseover,help,nodead][@player] {29166}", note = "Estimular al aliado bajo el ratón o a ti. En solitario, úsalo con poco maná para curarte y volver a felino." },
  },
})

Senda.Knowledge:Register({
  id = "druid-rotation",
  class = "DRUID",
  kind = "rotation",
  title = "Rotación del druida (feral)",
  levels = {1, 60},
  order = 100,
  status = "unverified",
  note = "Rotaciones de Warcraft Tavern (guías de druida y de feral de Forever) y Method (7-nov). Poder cambiante y Mordisco primario son talentos de Forever con ids de Warcraft Tavern.",
  phase = {
    { from = 1, to = 9, spells = {467, 5176, 8921, 774}, text = "1. Espinas y Marca de lo Salvaje puestas.\n2. Cólera para tirar.\n3. Fuego lunar.\n4. Cólera hasta que esté casi muerto o te falte maná.\n5. Remata con el arma. Rejuvenecimiento entre combates." },
    { from = 10, to = 19, spells = {5176, 8921, 5487, 5229, 99, 6807, 779}, text = "**Oso, un enemigo:**\n1. Cólera x2 y Fuego lunar mientras llega.\n2. Forma de oso, Enfurecer.\n3. Rugido desmoralizador (no contra lanzadores).\n4. Magullar en cada golpe; Azote si lanza.\n\n**Oso, varios:** Enfurecer, Rugido desmoralizador y Flagelo (16)." },
    { from = 20, to = 29, spells = {768, 5215, 5221, 770, 1082, 1079, 1822, 22568}, text = "**Felino:**\n1. Acechar y abre con Triturar por la espalda (o Cargar feral para saltar detrás).\n2. Fuego feérico.\n3. Arañar (desde el 24; sáltalo si va a morir ya).\n4. Arañazo hasta 4-5 puntos de combo (Triturar si estás detrás).\n5. Destripar si va a vivir todo el sangrado; si no, Mordedura feroz (24).\n\nSi te pegan varios: Forma de oso." },
    { from = 30, to = 39, spells = {768, 5215, 6785, 770, 1822, 1082, 1079, 22568}, text = "**Felino:**\n1. Acechar y abre con Devastar (32) por la espalda; si no, Triturar.\n2. Fuego feérico, Arañar.\n3. Arañazo (o Triturar detrás) hasta 5 puntos.\n4. Mordedura feroz con 4-5 puntos y 70+ de energía; Destripar en enemigos con mucha vida.\n5. Forma de viaje (30) para moverte entre grupos." },
    { from = 40, to = 60, spells = {768, 6785, 770, 1822, 1079, 22568, 1082, 1322605, 9634, 407995}, text = "**Felino:**\n1. Espinas puesta, Fuego feérico.\n2. **Poder cambiante** si tienes menos de 50 de energía (no lo gastes todo: el maná es para curarte).\n3. Destripar con 5 puntos; Mordedura feroz con 4-5 puntos y 70+ de energía.\n4. Arañar (sáltalo si va a morir ya).\n5. Arañazo para generar puntos; Triturar si estás detrás.\n\n**Oso temible (grupos o mazmorra):** Fuego feérico, Lacerar hasta 5 cargas, Rugido desmoralizador, Mordisco primario cuando esté listo, Flagelo (varios) o Magullar (uno).", note = "Poder cambiante (1322605) y Mordisco primario (407995): ids de Warcraft Tavern, sin comprobar." },
  },
  hud = {
    { when = "Sin objetivo, fuera de combate y hp < 0.6", suggest = "Cúrate en forma normal (Recrecimiento / Rejuvenecimiento)", spell = 8936 },
    { when = "Sin objetivo, fuera de combate y mana < 0.4", suggest = "Bebe agua" },
    { when = "hp < 0.3 y conoces Regeneración frenética y estás en oso", suggest = "Regeneración frenética", spell = 22842 },
    { when = "hp < 0.3 y no estás en oso", suggest = "Forma de oso (o Garras de la naturaleza y huye)", spell = 5487 },
    { when = "Estás en felino, energy < 50 y conoces Poder cambiante", suggest = "Poder cambiante", spell = 1322605 },
    { when = "Estás en felino, cp >= 5 y thp > 0.4", suggest = "Destripar", spell = 1079 },
    { when = "Estás en felino, cp >= 4 y conoces Mordedura feroz", suggest = "Mordedura feroz", spell = 22568 },
    { when = "Estás en felino y el objetivo no tiene Arañar", suggest = "Arañar", spell = 1822 },
    { when = "Estás en felino", suggest = "Arañazo (Triturar si estás detrás)", spell = 1082 },
    { when = "Estás en oso y rage >= 15", suggest = "Magullar", spell = 6807 },
    { when = "Estás en oso", suggest = "Enfurecer y Rugido desmoralizador", spell = 5229 },
    { when = "Siempre (último recurso)", suggest = "Cólera", spell = 5176 },
  },
  warning = {
    { text = "Sin Marca de lo Salvaje", when = "No tienes ninguna aura de [ids].mark_buffs (spells.toml)" },
    { text = "Sin Espinas", when = "No tienes ninguna aura de [ids].thorns_buffs y vas a pelear solo" },
    { text = "Talento(s) sin gastar", when = "Tienes puntos de talento sin gastar" },
    { text = "Sin Forma felina al 20", when = "Nivel >= 21 y no conoces Forma felina (misión El gran espíritu felino)" },
    { text = "Bolsas llenas", when = "Menos de 3 huecos libres" },
  },
})

Senda.Knowledge:Register({
  id = "druid-combat",
  class = "DRUID",
  kind = "page",
  title = "Combate en solitario",
  order = 110,
  status = "unverified",
  block = {
    { heading = "El combate básico (felino)", body = "1. Espinas y Marca de lo Salvaje puestas.\n2. Acecha y abre por la espalda (Triturar o Devastar). Fuego feérico.\n3. Arañar, Arañazo hasta 4-5 puntos de combo.\n4. Destripar si va para largo; Mordedura feroz si va a morir ya.\n5. Fuera de combate: forma normal, Recrecimiento o Rejuvenecimiento y vuelta a felino." },
    { heading = "Dos enemigos o más", body = "- **Forma de oso**: Rugido desmoralizador y Flagelo. Aguantas mucho más que en felino.\n- **Raíces enredadoras** al segundo (SND_Raices con foco) y mata al primero. En Forever valen en interiores.\n- **Hibernar** duerme bestias y dragonantes.\n- **Garras de la naturaleza** (de base): enraíza a quien te golpee. Úsala antes de tirar si temes una pelea doble." },
    { heading = "Energía y maná", body = "- **Augurio de claridad** es de base en Forever: el siguiente golpe o hechizo sale gratis.\n- **Poder cambiante** (talento del 40) cambia maná por 40 de energía sin salir del felino: sustituye al antiguo cambio de forma con poder. Úsalo con menos de 50 de energía.\n- **Furor** ya no da energía al cambiar de forma (la conserva): no merece la pena re-entrar en felino para ganar energía.\n- Bebe entre combates: el maná es tu vida (curas) y tu energía extra." },
    { heading = "Emergencias, por orden", body = "1. Forma de oso (más vida y armadura) y Regeneración frenética (36).\n2. Piel de corteza (44).\n3. Garras de la naturaleza o Raíces enredadoras y huye en felino (Carrerilla, 26).\n4. Sal de la forma y cúrate: Recrecimiento, Toque de sanación.\n5. Estimular (40) si te falta maná.\n6. Poción: en Forever las de sanación las hace Primeros auxilios, y puedes beberlas sin salir de la forma." },
    { heading = "Raciales de elfo de la noche en Forever", body = "- **Fusión de las sombras:** te ocultas quieto; combina con Acechar para reiniciar peleas.\n- **Luz de Elune** (Elune's Light, nueva): cooldown de crítico.\n- **Rapidez:** más esquiva y velocidad de movimiento.\n- **Espíritu de fuego fatuo:** al morir corres más como espíritu.", note = "Raciales según Warcraft Tavern; nombre esES de Luz de Elune sin confirmar." },
  },
})

Senda.Knowledge:Register({
  id = "druid-group",
  class = "DRUID",
  kind = "page",
  title = "Grupo, viajes y PvP",
  order = 120,
  status = "unverified",
  block = {
    { heading = "En mazmorra", body = "- Marca de lo Salvaje (Don de lo Salvaje al 50) y Espinas al tanque.\n- **Felino (daño):** espera 2-3 golpes del tanque, Fuego feérico, golpea por la espalda (Triturar). Agazaparse si te ven.\n- **Oso (tanque):** Fuego feérico, Lacerar x5, Mordisco primario, Rugido desmoralizador; Flagelo en grupos. Gruñido (SND_Gru) para recuperar enemigos y Rugido desafiante como último recurso.\n- **Cargar feral** en oso interrumpe lanzadores.\n- Curar envenenamiento, Eliminar maldición y Renacer (resurrección en combate; pide componente).\n- **Revivir** (12) resucita fuera de combate." },
    { heading = "Viajes", body = "- **Teletransporte: Claro de la Luna** (10): instructor de druida y maestro de vuelo a Darnassus.\n- **Forma de viaje** (30) y **Forma acuática** (16): SND_Viaje elige sola.\n- Desde Auberdine: barco a Menethil (Reinos del Este) y a Rut'theran (Darnassus)." },
    { heading = "PvP", body = "- **Elfo de la noche:** Fusión de las sombras y Acechar te dejan elegir la pelea.\n- **Contra guerreros y pícaros:** Raíces enredadoras y distancia; Forma de oso si te aturden mucho.\n- **Contra lanzadores:** Abalanzarse desde Acechar, Azote o Cargar feral (oso) para cortar.\n- **Contra cazadores:** pégate a ellos y quítate las ralentizaciones con SND_Gato.\n- Cambiar de forma te libra de raíces y ralentizaciones." },
  },
})

