  bindings = { ["SHIFT-1"] = "MULTIACTIONBAR1BUTTON1", ["SHIFT-2"] = "MULTIACTIONBAR1BUTTON2", ["SHIFT-3"] = "MULTIACTIONBAR1BUTTON3", ["SHIFT-4"] = "MULTIACTIONBAR1BUTTON4", ["SHIFT-5"] = "MULTIACTIONBAR1BUTTON5", ["SHIFT-6"] = "MULTIACTIONBAR1BUTTON6" },
  block = {
    { heading = "Consejos de barras", body = "- Coloca cada barra **estando en esa forma**: el juego guarda una barra distinta para normal, felino y oso.\n- Deja las mismas teclas para lo mismo en las tres: 1 = abrir/golpe principal, 4 = Fuego feérico, 8 = Cargar feral, 12 = cambiar de forma.\n- SND_Cura sale de la forma y te cura: tenla también en la barra de felino y oso si quieres (cuesta un cambio de forma volver).\n- En Classic las barras no suben de rango solas: vuelve a colocar los hechizos después de entrenar." },
  },
})

Senda.Knowledge:Register({
